document.addEventListener('DOMContentLoaded', () => {
  const setTheme = t => {
    document.documentElement.setAttribute('data-bs-theme', t);
    localStorage.setItem('theme', t);
    const icon = document.querySelector('.btn-dark-mode i');
    if (icon) icon.className = t === 'dark' ? 'bi bi-sun-fill text-warning' : 'bi bi-moon-stars-fill';
  };

  const getTheme = () =>
    localStorage.getItem('theme') ||
    (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');

  setTheme(getTheme());

  document.querySelectorAll('.btn-dark-mode').forEach(btn => {
    btn.addEventListener('click', () =>
      setTheme(document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'light' : 'dark')
    );
  });
});
